const D = { relief: .6, rough: .55, energy: .6, speed: 1, density: .5, scale: 1, hue: 270, x: .5, y: .8, style: 'dusk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- full-size scene buffer (enables alpha compositing without clearing main) ----
if (!S.g || S.key !== width + 'x' + height) { S.g = createGraphics(width, height); S.g.pixelDensity(1); S.key = width + 'x' + height; }
const g = S.g;

// ---- seed-deterministic per-octave phase offsets ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.ph = []; for (let n = 0; n < 8; n++) S.ph[n] = fr(n + 1) * 6.2831853;
  S.cph = []; for (let n = 0; n < 6; n++) S.cph[n] = fr(n + 20) * 6.2831853; // per-curtain / per-ridge jitter
}

const uMin = Math.min(width, height);
const TAU = 6.2831853;
const style = P.style;
const spd = 0.3 + P.speed;                 // scroll/drift multiplier (never zero-floor to 0 → still drifts a bit)
const expo = 0.55 + P.energy * 0.7 + K.intensity * 0.3 + A.rms * 0.5;
const sec = K.section | 0;
const hshift = sec * 9 + Math.sin(K.t * 0.03) * 6; // slow dramaturgical palette drift
const H = h => ((h % 360) + 360) % 360;
const lerp2 = (a, b, t) => a + (b - a) * t;

// ---- Weierstrass fractal profile ----
const a = 0.45 + P.rough * 0.40;           // amplitude decay (higher = rougher / more high-freq)
const N = 5 + Math.round(P.rough * 3);     // octaves 5..8
const b = 1.9;                             // lacunarity (a*b>1 → nowhere-differentiable)
let sumAmp = 0, ap = 1; for (let n = 0; n < N; n++) { sumAmp += ap; ap *= a; }
// phases drift continuously on K.t (never re-phase) + seed offset
const drift = []; for (let n = 0; n < N; n++) drift[n] = K.t * (0.12 + n * 0.045) * spd + S.ph[n];
function W(phaseX) {
  let hh = 0, ampp = 1, ff = 1;
  for (let n = 0; n < N; n++) { hh += ampp * Math.cos(TAU * ff * phaseX + drift[n]); ampp *= a; ff *= b; }
  return hh / sumAmp;
}

// ---- style palettes ----
function skyCol(f) { // f: 0 top .. 1 horizon
  if (style === 'aurora') return [H(lerp2(225, 208, f) + hshift * .3), lerp2(78, 44, f), lerp2(7, 17, f)];
  if (style === 'ink')    return [H(lerp2(42, 34, f)), lerp2(7, 13, f), lerp2(90, 80, f)];
  if (style === 'neon')   return [H(lerp2(252, 288, f) + hshift), lerp2(62, 52, f), lerp2(5, 11, f)];
  if (style === 'mars')   return [H(lerp2(11, 30, f) + hshift * .2), lerp2(46, 60, f), lerp2(40, 78, f)];
  // dusk (default): violet crown -> amber horizon (go up through red, not through green)
  return [H(lerp2(P.hue + 2, P.hue + 122, f) + hshift), lerp2(55, 84, f), lerp2(20, 74, f) * (0.85 + expo * 0.2)];
}
function ridgeCol(depth) { // depth 0 far .. 1 near
  if (style === 'aurora') return [H(lerp2(220, 226, depth)), lerp2(48, 62, depth), lerp2(16, 5, depth)];
  if (style === 'ink')    return [H(lerp2(40, 28, depth)), lerp2(5, 8, depth), lerp2(74, 20, depth)];
  if (style === 'neon')   return [H(lerp2(300, 300, depth)), 55, lerp2(15, 9, depth)];
  if (style === 'mars')   return [H(lerp2(15, 9, depth)), lerp2(42, 66, depth), lerp2(55, 18, depth)];
  return [H(lerp2(P.hue + 15, P.hue + 122, depth)), lerp2(46, 68, depth), lerp2(54, 15, depth)]; // dusk
}
function rimCol(depth) {
  if (style === 'aurora') return [H(lerp2(160, 185, depth)), 82, lerp2(65, 92, depth)];
  if (style === 'ink')    return [H(30), 10, lerp2(58, 14, depth)];
  if (style === 'neon')   return [H(lerp2(322, 176, depth)), 92, 100];
  if (style === 'mars')   return [H(22), 60, lerp2(80, 40, depth)];
  return [H(lerp2(P.hue + 40, 40, depth)), 70, lerp2(78, 48, depth) + expo * 8]; // dusk warm glow rim
}

// ========================= RENDER =========================
g.push();
// sky gradient (banded)
g.noStroke();
const nB = 100, horizon = height * lerp2(0.30, 0.52, P.y);
for (let i = 0; i < nB; i++) {
  const f = i / (nB - 1);
  const c = skyCol(f);
  g.fill(c[0], c[1], c[2]);
  g.rect(0, f * height - 1, width, height / nB + 2);
}

// atmospheric glow / curtains (per style, partial — never full-frame flash)
g.blendMode(ADD);
const glowPulse = 0.6 + 0.4 * Math.sin(K.t * 0.5) + K.swell * 0.5 + A.bass * 0.6;
if (style === 'aurora') {
  for (let i = 0; i < 5; i++) {
    const cx = (i / 5 + 0.1 + 0.08 * Math.sin(K.t * 0.2 * spd + i * 1.7)) % 1 * width;
    const sh = 0.5 + 0.5 * Math.sin(K.t * 0.6 * spd + S.cph[i]);
    const hue = [150, 172, 128, 200, 285][i];
    for (let s = 0; s < 5; s++) {
      g.fill(hue, 75, 22 * sh * (0.4 + expo * 0.5), 1);
      g.rect(cx - width * 0.05 + s * width * 0.006, 0, width * 0.05, horizon * 1.1);
    }
  }
} else if (style !== 'ink') {
  // warm/cool sun-glow bloom near horizon at anchor x
  const sx = P.x * width, sy = horizon * (0.95 + 0.03 * Math.sin(K.t * 0.4));
  const gh = style === 'neon' ? H(lerp2(300, 200, P.x) + hshift) : (style === 'mars' ? 32 : H(P.hue + 118 + hshift));
  for (let r = 0; r < 7; r++) {
    const rad = uMin * (0.08 + r * 0.09);
    g.fill(gh, style === 'mars' ? 55 : 60, (14 - r * 1.6) * glowPulse * (0.5 + expo * 0.4), 1);
    g.ellipse(sx, sy, rad * 2, rad * 1.3);
  }
}
g.blendMode(BLEND);

// ---- parallax ridge silhouettes, back -> front ----
const nR = 4 + Math.round(P.density * 2);   // 4..6 ridges
const nCols = 150;
for (let k = 0; k < nR; k++) {
  const depth = nR === 1 ? 0 : k / (nR - 1);
  const baseY = height * (0.34 + depth * 0.44) + (P.y - 0.8) * height * 0.10;
  const amp = uMin * (0.045 + depth * 0.13) * (0.35 + P.relief * 1.1);
  const cyc = (2.0 + depth * 3.0) * (0.55 + P.scale * 0.75);
  const scroll = K.t * (0.012 + depth * 0.05) * spd + S.cph[k] * 0.3;
  const audioLift = (A.bass * 0.5 + K.pulse * 0.25) * amp * 0.6 * depth;
  const rc = ridgeCol(depth);

  // build profile
  const ys = new Array(nCols);
  for (let i = 0; i < nCols; i++) {
    const xf = i / (nCols - 1);
    ys[i] = baseY - W(xf * cyc + scroll) * amp - audioLift;
  }

  // fill silhouette
  if (style === 'neon') { g.fill(rc[0], 60, rc[2] + 6); } else { g.fill(rc[0], rc[1], rc[2]); }
  g.noStroke();
  g.beginShape();
  g.vertex(0, height + 4);
  for (let i = 0; i < nCols; i++) g.vertex(i / (nCols - 1) * width, ys[i]);
  g.vertex(width, height + 4);
  g.endShape(CLOSE);

  // crest rim / glow line
  const rim = rimCol(depth);
  const nb = (style === 'neon');
  if (nb) { g.drawingContext.shadowBlur = 14 + depth * 10; g.drawingContext.shadowColor = 'hsl(' + rim[0] + ',100%,60%)'; }
  g.noFill();
  g.stroke(rim[0], rim[1], rim[2], nb ? 100 : (style === 'ink' ? 55 : 70));
  g.strokeWeight(nb ? 2.0 : (style === 'ink' ? 1.3 : 1.4) + depth * 0.6);
  g.beginShape();
  for (let i = 0; i < nCols; i++) g.vertex(i / (nCols - 1) * width, ys[i]);
  g.endShape();
  if (nb) g.drawingContext.shadowBlur = 0;
}
g.pop();

// ---- blit to main (tint enables translucent VJ compositing at alpha<100) ----
push();
if (P.alpha < 100) { tint(0, 0, 100, P.alpha); } else { noTint(); }
image(g, 0, 0, width, height);
pop();

// ---- treble shimmer on nearest crags (partial, additive — won't strobe) ----
if (A.treble > 0.02) {
  push(); blendMode(ADD); noStroke();
  fill(H(P.hue + 60), 40, 100, Math.min(18, A.treble * 30));
  rect(0, height * 0.55, width, height * 0.45);
  blendMode(BLEND); pop();
}
